import io
import json
import math
import subprocess
from PIL import Image, ImageDraw, ImageFont


def adapt(path):
    duration = 0.0
    try:
        p = subprocess.run(['ffprobe', '-v', 'error', '-show_entries', 'format=duration:stream=duration', '-of', 'json', path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=8)
        info = json.loads(p.stdout)
        vals = [info.get('format', {}).get('duration')] + [s.get('duration') for s in info.get('streams', [])]
        vals = [float(v) for v in vals if v is not None and v != 'N/A']
        duration = max([v for v in vals if math.isfinite(v) and v > 0] or [0.0])
    except Exception:
        pass

    frames = []
    if duration > 0:
        # Decode a uniform sequence in one pass, then select additional frames
        # around the largest visual changes.
        count = 48
        rate = min(8.0, count / duration)
        try:
            cmd = ['ffmpeg', '-v', 'error', '-i', path, '-vf', 'fps=%.8f,scale=240:180:force_original_aspect_ratio=decrease,pad=240:180:(ow-iw)/2:(oh-ih)/2' % rate, '-frames:v', str(count), '-f', 'image2pipe', '-vcodec', 'mjpeg', '-q:v', '3', 'pipe:1']
            p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=35)
            data = p.stdout
            pos = 0
            while len(frames) < count:
                start = data.find(b'\xff\xd8', pos)
                if start < 0:
                    break
                end = data.find(b'\xff\xd9', start + 2)
                if end < 0:
                    break
                try:
                    im = Image.open(io.BytesIO(data[start:end + 2])).convert('RGB')
                    frames.append(im)
                except Exception:
                    pass
                pos = end + 2
        except Exception:
            pass

    if not frames:
        try:
            import adapter_kit
            frames = [im.convert('RGB') for im in adapter_kit.video_frames(path, n=12)]
            rate = (len(frames) / duration) if duration > 0 else 1.0
        except Exception:
            frames = []
    if not frames:
        return {'images': [Image.new('RGB', (256, 128), 'black')]}

    n = len(frames)
    # 24 chronological frames: 16 evenly spaced plus 8 from high-change intervals.
    target = min(24, n)
    base = min(16, target)
    chosen = set(round(i * (n - 1) / max(1, base - 1)) for i in range(base))
    if len(chosen) < target:
        try:
            import numpy as np
            small = [np.asarray(im.convert('L').resize((48, 36)), dtype=np.int16) for im in frames]
            scores = [(float(np.mean(np.abs(small[i] - small[i - 1]))), i) for i in range(1, n)]
            for _, i in sorted(scores, reverse=True):
                if len(chosen) >= target:
                    break
                if i not in chosen:
                    chosen.add(i)
        except Exception:
            pass
    for i in range(n):
        if len(chosen) >= target:
            break
        chosen.add(i)
    selected = sorted(chosen)

    # Four frames per sheet preserve enough detail while showing temporal order.
    sheets = []
    font = ImageFont.load_default()
    for start in range(0, len(selected), 4):
        group = selected[start:start + 4]
        sheet = Image.new('RGB', (512, 416), 'white')
        draw = ImageDraw.Draw(sheet)
        for j, idx in enumerate(group):
            x = (j % 2) * 256
            y = (j // 2) * 208
            im = frames[idx].copy()
            im.thumbnail((252, 184), Image.Resampling.LANCZOS)
            sheet.paste(im, (x + (256 - im.width) // 2, y + 18 + (184 - im.height) // 2))
            t = (idx + 0.5) / rate if rate > 0 else float(idx)
            if duration > 0:
                t = min(t, duration)
            draw.text((x + 4, y + 3), '%.2f s' % t, fill='black', font=font)
        sheets.append(sheet)
    return {'images': sheets[:9]}
